def transform(grid):
    h, w = len(grid), len(grid[0])

    # Split at a uniform row or column.
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            first, second = grid[:r], grid[r + 1:]
            a = first
            b = second
            break
    else:
        for c in range(w):
            if len({grid[i][c] for i in range(h)}) == 1:
                a = [row[:c] for row in grid]
                b = [row[c + 1:] for row in grid]
                break

    # Mark positions where the two panels have the same non-background
    # symbol, keeping the first panel's background elsewhere.
    from collections import Counter
    ca = Counter(v for row in a for v in row)
    bg = ca.most_common(1)[0][0]
    return [
        [3 if x == y and x != bg else bg for x, y in zip(ar, br)]
        for ar, br in zip(a, b)
    ]
